public class HiddenScopeRuntime {
 static List<Object> leaves(org.eclipse.xtext.nodemodel.INode node){List<Object> result=new ArrayList<>();if(node!=null)for(var leaf:node.getLeafNodes())result.add(fields("text",leaf.getText(),"hidden",leaf.isHidden(),"utf16_start",leaf.getOffset(),"utf16_end",leaf.getEndOffset(),"syntax_error",leaf.getSyntaxErrorMessage()==null?null:leaf.getSyntaxErrorMessage().getMessage()));return result;}
 static List<Object> modelNodes(EObject root){List<Object> result=new ArrayList<>();if(root==null)return result;List<EObject> all=new ArrayList<>();all.add(root);root.eAllContents().forEachRemaining(all::add);for(var object:all){var node=NodeModelUtils.getNode(object);result.add(fields("class",object.eClass().getEPackage().getNsURI()+"#//"+object.eClass().getName(),"utf16_start",node==null?null:node.getOffset(),"utf16_end",node==null?null:node.getEndOffset(),"total_utf16_start",node==null?null:node.getTotalOffset(),"total_utf16_end",node==null?null:node.getTotalEndOffset()));}return result;}
